<template><div class="page"><div class="section-title"><div><h2>日常工单</h2><span class="muted">{{order?.title}} · {{order?.status}}</span></div><n-space><n-button @click="complete">完成</n-button><n-button type="error" @click="cancel">取消工单</n-button></n-space></div><div class="panel"><n-descriptions bordered :column="2"><n-descriptions-item label="类型">{{order?.type}}</n-descriptions-item><n-descriptions-item label="目标">{{order?.target}}</n-descriptions-item><n-descriptions-item label="描述" :span="2">{{order?.description}}</n-descriptions-item></n-descriptions></div><section class="panel chat-main" style="height:55vh"><div class="messages"><div v-for="(m,i) in messages" :key="i" :class="['message',m.role]">{{m.content}}</div></div><div class="chat-input"><n-input v-model:value="input" placeholder="与工单 Agent 讨论方案、配置或脚本..." @keydown.enter.exact.prevent="send"/><n-button type="primary" :loading="streaming" @click="send">发送</n-button></div></section></div></template>
<script setup>import {ref,onMounted} from 'vue';import {useRoute} from 'vue-router';import {workOrderApi,request,streamConversation} from '@/api';const route=useRoute(),order=ref(null),messages=ref([]),input=ref(''),streaming=ref(false);async function load(){order.value=await workOrderApi.get(route.params.id);const r=await request.get(`/work-orders/${route.params.id}/messages`);messages.value=(r.messages||[]).map(x=>({role:x.role,content:x.content}))}async function send(){const q=input.value.trim();if(!q||streaming.value)return;input.value='';messages.value.push({role:'user',content:q},{role:'assistant',content:''});streaming.value=true;try{await streamConversation(`/work-orders/${route.params.id}/chatStream`,q,t=>messages.value.at(-1).content+=t)}finally{streaming.value=false}}async function complete(){await workOrderApi.complete(route.params.id);await load()}async function cancel(){await workOrderApi.cancel(route.params.id);await load()}onMounted(load)</script>
